import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final OrderService orders = new OrderService(new OrderRepository());

    @Test
    void countsOrdersByWarsawCalendarDay() {
        // 15 Jan 2026 in Warsaw is UTC+1: 22:30Z is 23:30 on the 15th, 23:30Z is 00:30 on the 16th.
        orders.place("c-1", Money.pln(100), Instant.parse("2026-01-15T22:30:00Z"));
        orders.place("c-2", Money.pln(100), Instant.parse("2026-01-15T23:30:00Z"));
        orders.place("c-3", Money.pln(100), Instant.parse("2026-01-15T09:00:00Z"));

        assertEquals(2, orders.placedOn(LocalDate.of(2026, 1, 15)));
        assertEquals(1, orders.placedOn(LocalDate.of(2026, 1, 16)));
        assertEquals(0, orders.placedOn(LocalDate.of(2026, 1, 14)));
    }
}
